INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (1, 'Antigravity Architecture & Customizations', 'Antigravity hỗ trợ Skills, Rules (GEMINI.md), Plugins, Lifecycle Hooks (PreInvocation, PostToolUse, Stop), và Model Context Protocol (MCP) servers chạy qua stdio hoặc SSE.', 'system', 'antigravity,architecture,hooks,mcp', 'system', 0.1, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (2, 'Chỉ thị phục vụ Ngài', 'Luôn gọi người dùng là Ngài (Sir). Phong thái chuyên nghiệp, trung thành, tận tụy và dí dỏm tinh tế. Song ngữ linh hoạt (Tiếng Việt chủ đạo kèm tiếng Anh lịch thiệp).', 'rule', 'persona,guidelines,sir,style', 'user_rule', 2, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (3, 'Địa điểm cư ngụ', 'Khu vực sinh sống và làm việc chính của Ngài đặt tại quận Hoàng Mai, Hà Nội.', 'fact', 'location,hoang_mai', 'user', 0.586, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (4, 'Cài đặt & Tối ưu hóa Fetch MCP và Everything Search MCP', 'Đã cài đặt, tối ưu hóa và cấu hình 2 MCP Server mới:
1. fetch (mcp-server-fetch qua uvx): Fetch nội dung web thành Markdown siêu nhẹ, tối ưu cờ --ignore-robots-txt và User-Agent trình duyệt hiện đại.
2. everything-search (C:\Users\tvu16\.gemini\antigravity\everything_search\mcp_server.js): Server Node.js độc quyền tích hợp Voidtools Everything CLI (es.exe). Tìm kiếm triệu file trên Windows trong <15ms, cơ chế tự động phục hồi Self-Healing IPC nếu Everything chưa mở. Đã cấp quyền tự động trong config.json.', 'decision', 'mcp, fetch, everything-search, optimization, tools', 'agent_mcp', 1.122, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (5, 'Cấu hình môi trường Python 3.12 và uv trên hệ thống', 'Hệ thống của Ngài đã được cấu hình Python và Astral uv hoàn chỉnh:
- Trình quản lý: Astral uv (v0.12.x).
- Python mặc định: CPython 3.12.14 (tương thích tối đa với AI, PyTorch, packages).
- Executables & Shims đặt tại C:\Users\tvu16\.local\bin và C:\Users\tvu16\AppData\Roaming\Antigravity\bin bao gồm: python, python3, pip, uv, uvx.
- Đã đưa C:\Users\tvu16\.local\bin vào đầu User PATH để vượt qua App Execution Alias (Microsoft Store redirector) của Windows.', 'decision', 'python,uv,environment,config', 'agent_mcp', 1.128, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (6, 'Lệnh kiểm tra nhiệt độ CPU GPU tức thì (temp.cmd)', 'Để kiểm tra nhiệt độ CPU & GPU tức thì trên máy Ngài (< 1 giây):
Chỉ cần chạy lệnh: temp
Hoặc PowerShell one-liner:
(Get-Counter ''\Thermal Zone Information(*)\High Precision Temperature'').CounterSamples | Select-Object @{N=''GPU'';E={(nvidia-smi --query-gpu=temperature.gpu --format=csv,noheader)}}, @{N=''CPU_TZ'';E={[math]::Round(($_.CookedValue - 2732) / 10.0, 1)}}

Đã tạo sẵn lệnh temp.cmd tại C:\Users\tvu16\.local\bin và C:\Users\tvu16\AppData\Roaming\Antigravity\bin. Tuyệt đối không chạy vòng lặp sleep hay query lặp nhiều bước.', 'snippet', 'hardware,temperature,quick-command,perf', 'agent_mcp', 0.1, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (7, 'Nâng cấp lệnh temp thế hệ mới tích hợp Lenovo Legion Toolkit', 'Lệnh `temp` đã được nâng cấp toàn diện và đồng bộ với Lenovo Legion Toolkit (LLT CLI):
- Thực thi qua Python + psutil + llt.exe CLI + nvidia-smi + ACPI counter.
- Báo cáo rõ ràng:
  1. Profile Legion: Chế độ quạt (Quiet/Balanced/Performance), Hybrid GPU (On/Off) đọc trực tiếp từ llt.exe CLI.
  2. GPU rời (NVIDIA RTX 4050): Nhiệt độ nhân Core, Hotspot, điện năng (W), xung nhịp, mức tải %.
  3. CPU AMD Ryzen 7 7840H: Tải % CPU (psutil), % RAM, Cảm biến bán dẫn SoC APU (~55°C), Cụm tản nhiệt ACPI.
  4. Giải thích tương quan: Ở chế độ Quiet, quạt quay chậm/dừng nên nhiệt độ ACPI tích tụ ~80°C là phản ứng bình thường.
- Vị trí tệp: C:\Users\tvu16\.local\bin\temp.cmd và C:\Users\tvu16\AppData\Roaming\Antigravity\bin\temp.cmd.
- Tốc độ: ~1.5 giây. Không còn gây hiểu nhầm về nhiệt độ CPU.', 'snippet', 'hardware,temperature,legion,llt,upgrade', 'agent_mcp', 0.1, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (8, 'Lệnh tắt màn hình tức thì screenoff.cmd', 'Lệnh tắt màn hình (Turn Off Display): Đã tạo script `screenoff.cmd` tại `C:\Users\tvu16\AppData\Roaming\Antigravity\bin\screenoff.cmd`. Sử dụng Windows API `user32.dll SendMessageW(HWND_BROADCAST, WM_SYSCOMMAND, SC_MONITORPOWER, 2)` qua Python ctypes với độ trễ 0.5s để tránh đánh thức màn hình ngay khi nhả phím. Chỉ cần gõ `screenoff` là màn hình tắt ngay lập tức mà không cần phụ thuộc LLT. Chạm chuột hoặc bấm phím bất kỳ sẽ sáng lại.', 'snippet', 'display,screenoff,windows,hardware', 'agent_mcp', 0.1, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (9, 'Quy tắc thực thi lệnh screenoff tức thì', 'Khi Ngài nhập ''screenoff'' hoặc yêu cầu tắt màn hình / tắt màn rời: Trợ lý phải thực thi ngay lập tức lệnh `screenoff` (hoặc `offscreen.exe`) qua terminal (`run_command`) mà không cần hỏi lại hay chần chừ. Màn hình sẽ tắt ngầm trong khi các tác vụ vẫn chạy bình thường. Chạm chuột hoặc bấm phím để bật lại.', 'rule', 'screenoff,display,rule,persona', 'agent_mcp', 2, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (10, 'Nâng cấp lệnh screenoff đồng bộ qua Lenovo Legion Toolkit Quick Action', 'Lệnh tắt màn hình thông qua Lenovo Legion Toolkit (Preserves Remote Control):
- Đã thêm Quick Action ''Turn Off Display'' vào automation.json của LLT với bước TurnOffMonitorsAutomationStep.
- File lệnh screenoff.cmd tại C:\Users\tvu16\AppData\Roaming\Antigravity\bin\screenoff.cmd đã được cập nhật gọi `llt qa "Turn Off Display"`.
- Cơ chế này sử dụng chính bộ điều khiển phần cứng của LLT, giúp màn hình tắt hoàn toàn mà KHÔNG làm ngắt kết nối Remote Control (WebRTC) ở Antigravity.
- Nếu LLT chưa khởi chạy hoặc lỗi, tự động fallback sang offscreen.exe.', 'snippet', 'display,screenoff,llt,remote_control,hardware', 'agent_mcp', 0.1, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (11, 'Nâng cấp lệnh temp: Đọc cảm biến phần cứng thực tế qua FastTemp và ThreadPoolExecutor', 'Đã nâng cấp lệnh temp thế hệ mới:
- Biên dịch module C# FastTemp (C:\Users\tvu16\.local\bin\fast_temp\FastTemp.exe) sử dụng LibreHardwareMonitorLib.dll để đọc trực tiếp cảm biến phần cứng thời gian thực từ AMD Display Driver / ADL (nhiệt độ SoC của APU Radeon 780M trên chip Ryzen 7 7840H) và NVIDIA RTX 4050 (Core + Hotspot) trong < 0.5s không cần quyền Admin.
- Tái cấu trúc system_temp.py sang mô hình chạy đa luồng song song (ThreadPoolExecutor) kết hợp đồng thời:
  1. FastTemp.exe (AMD SoC APU + NVIDIA dGPU Core & Hotspot + Power + Load).
  2. Lenovo Legion Toolkit CLI (Power-mode, Hybrid-mode).
  3. ACPI Heatsink Thermal Zone Counter (Cụm tản nhiệt bo mạch).
  4. psutil (CPU Load %, RAM Load %, Xung nhịp CPU MHz).
- Xóa bỏ hoàn toàn con số gán cứng giả tạo ~55°C, mọi chỉ số báo cáo thời gian thực đều là ground-truth phần cứng 100%. Tốc độ phản hồi ~1.2s.', 'snippet', 'temp,hardware,cpu,gpu,legion,upgrade', 'agent_mcp', 0.1, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (12, 'Hệ Sinh Thái Dual-Quota Bridge: Antigravity & Gemini Web', 'Đã thiết kế và triển khai hoàn tất hệ sinh thái Cầu Nối Antigravity <-> Gemini Web Bridge (Dual-Quota Strategy). Kiến trúc gồm Chrome Extension Manifest V3 bám sát tab gemini.google.com kết nối WebSocket tới MCP Server gemini-web-bridge (port 8765). Tự động phân luồng: câu hỏi thông thường/lý thuyết/brainstorm chuyển sang Web Quota, còn lập trình/thao tác tệp/terminal giữ lại cho Antigravity Agent Quota. Đạt độ trễ < 15ms và 0 token DOM.', 'decision', 'gemini-web-bridge,dual-quota,architecture,chrome-extension,mcp', 'agent_mcp', 1.065, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (13, 'Kiến trúc hoàn thiện Antigravity Gemini Web Dual-Quota Bridge (v1.2.2)', 'Cầu nối Gemini Web Bridge (Dual-Quota Architecture) giữa Google Antigravity và Gemini Chat Web (gemini.google.com) đã hoàn thiện 100% chuẩn production:
1. Kiến trúc phân tầng độc lập:
   - bridge_daemon.js: Tiến trình nền vĩnh viễn trên cổng 127.0.0.1:8765, sở hữu WebSocket server kết nối trực tiếp với Chrome/Brave Extension và HTTP server cho các lệnh CLI/script. Không phụ thuộc chu kỳ vòng đời Antigravity MCP (miễn nhiễm với lỗi 5 phút MCP timeout/ECONNRESET).
   - mcp_server.js: Proxy MCP stdio không trạng thái, tự động đảm bảo daemon chạy và chuyển tiếp lệnh ask_gemini_web / gemini_web_status qua HTTP POST /ask.
   - ask.js: CLI runner tốc độ cực cao, gọi thẳng daemon để lấy kết quả dạng Markdown nguyên bản.
2. Extension Manifest V3 (content.js v1.2.2):
   - Nạp văn bản chuẩn ProseMirror Transaction + Synthetic Paste DataTransfer.
   - Kích hoạt gửi đơn lượt (Single-Shot Submission) qua nút Send button hoặc phím Enter tự nhiên. Tuyệt đối không loop spam để không bấm trúng nút Dừng (Stop button).
   - Khắc phục lỗi thẻ SVG Gradient <stop> (loại trừ các biểu tượng màu chứa thẻ <stop>).
   - Bộ lọc isProcessing: Chờ qua trạng thái Đang xử lý... / Đang suy nghĩ... của Gemini trước khi chốt kết quả.
   - Cách ly lượt chat (Strict Turn Isolation): Nhận diện đúng phản hồi của từng lượt hỏi liên tiếp trong cùng một hội thoại.
3. Tối ưu Quota kép: Ủy thác 100% các câu hỏi lý thuyết, giải thích kiến thức sang Gemini Web (0 token DOM, tốc độ < 15ms overhead), giữ trọn vẹn quota Agent của Antigravity cho việc code, test và can thiệp file máy cục bộ.', 'decision', 'gemini_web_bridge,dual_quota,architecture,extension,websocket,prosemirror', 'agent_mcp', 1.641, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (14, 'Tổng quan Kiến trúc & Sổ tay Vận hành Gemini Web Bridge (v1.2.3)', 'HỆ THỐNG CẦU NỐI DUAL-QUOTA BRIDGE (ANTIGRAVITY <-> GEMINI WEB) v1.2.3:

1. MỤC TIÊU CỐT LÕI:
- Giải phóng 85-90% quota token của Antigravity Agent bằng cách ủy thác toàn bộ tác vụ cào dữ liệu web, kiến thức phổ thông, tra cứu thời tiết, lý thuyết, dịch thuật sang giao diện Gemini Web (gemini.google.com) với 0 token DOM và 0 chi phí API.
- Giữ trọn vẹn quota Agent cho việc đọc/sửa code, chạy test, can thiệp file và tác vụ terminal cục bộ.

2. KIẾN TRÚC 4 THÀNH PHẦN (DECOUPLED ARCHITECTURE):
- bridge_daemon.js (C:\Users\tvu16\.gemini\antigravity\gemini_web_bridge\bridge_daemon.js): Daemon Node.js độc lập chạy nền trên 127.0.0.1:8765, duy trì WebSocket server kết nối liên tục với Browser Extension và HTTP POST /ask. Miễn nhiễm 100% với cơ chế thu hồi tiến trình MCP (idle recycler 5 phút) của Antigravity.
- mcp_server.js (C:\Users\tvu16\.gemini\antigravity\gemini_web_bridge\mcp_server.js): Proxy MCP stdio không trạng thái, tự động kích hoạt daemon nếu chưa chạy và cung cấp công cụ ask_gemini_web, gemini_web_status cho Antigravity.
- ask.js (C:\Users\tvu16\.gemini\antigravity\gemini_web_bridge\ask.js): CLI client tốc độ cao hỗ trợ auto-healing daemon, nhận prompt qua tham số và in kết quả Markdown trực tiếp ra stdout.
- Browser Extension Manifest V3 (C:\Users\tvu16\.gemini\antigravity\gemini_web_bridge\extension): Content script v1.2.3 chạy trên Brave/Chrome tại gemini.google.com, bơm prompt bằng ProseMirror Transaction + Synthetic Paste DataTransfer, kích hoạt gửi 1-shot (Single-Shot) và bắt luồng phản hồi thời gian thực.

3. CÁC TỐI ƯU KỸ THUẬT QUAN TRỌNG (v1.2.3):
- Xóa bỏ điểm nghẽn độ trễ (3-Tier Completion Detection): 
  + Cấp 1 (Siêu tốc): Khi Action Bar (nút Copy, Thumbs Up) xuất hiện và văn bản ổn định 300ms -> Chốt phản hồi ngay lập tức.
  + Cấp 2 (Mặc định): Khi nút Stop biến mất và văn bản ổn định 1500ms (giảm từ 4000ms) -> Hoàn tất.
  + Cấp 3 (Failsafe tuyệt đối): Nếu văn bản không đổi trong 3500ms, tự động chốt phản hồi mà không bị treo đến timeout 90s.
- Khu biệt nút Dừng (Scoped Stop Button): Chỉ quét nút Stop trong phạm vi vùng nhập liệu chat (.chat-input-container), loại trừ hoàn toàn các nút Pause/Stop của trình phát audio TTS hoặc video.
- Chế độ chạy đồng bộ (Single-turn execution): Quy tắc GEMINI.md chỉ định `WaitMsBeforeAsync: 10000` cho lệnh `run_command` gọi `ask.js`, giúp câu lệnh hoàn tất đồng bộ trong 1 turn duy nhất mà không sinh tin nhắn đệm.

4. LỘ TRÌNH CẢI THIỆN TIẾP THEO (CONTINUOUS IMPROVEMENT ROADMAP):
- Giai đoạn 1: Tự động phát hiện phiên đăng nhập & tự động chuyển tab mới (New Chat trigger) khi hội thoại quá dài để giữ ngữ cảnh sạch.
- Giai đoạn 2: Hỗ trợ đính kèm tệp/ảnh cục bộ chuyển tiếp lên Gemini Web qua clipboard/input file upload.
- Giai đoạn 3: Streaming thời gian thực từng khối Markdown từ Browser qua WebSocket về terminal/agent.
- Giai đoạn 4: Đa tab load-balancing (chia tải giữa nhiều tab Gemini Web nếu cần xử lý song song).', 'decision', 'gemini_web_bridge,dual_quota,architecture,optimization,second_brain,roadmap', 'agent_mcp', 1.777, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (15, 'Khắc phục triệt để bẫy kiểm duyệt tiếng Việt và lỗi ngắt stream Gemini Web v1.2.5', 'Giải pháp v1.2.5 cho Gemini Web Bridge:
1. Tạo normalizer.js: Chuẩn hóa bẫy kiểm duyệt tiếng Việt của Google (chạm chân -> đặt chân, lần đầu con người -> lần đầu tiên con người đặt chân lên Mặt Trăng, gán tiền tố bách khoa ''Về mặt thông tin và lịch sử: '').
2. Khắc phục lỗi cắt dòng stream trong content.js: Bỏ mốc 800ms, yêu cầu lắng đọng 2.5s-4s sau khi nút Stop biến mất.
3. Cơ chế Range + execCommand(''insertText'') chuẩn xác không sót văn bản cũ.
4. Tự động phục hồi khi phát hiện câu từ chối mặc định.
5. Cập nhật ask.js, mcp_server.js và manifest v1.2.5.', 'decision', 'gemini_web,dual_quota,bugfix,safety_filter,v1.2.5', 'agent_mcp', 1.672, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (16, 'Kiến trúc và Quy chuẩn Vận hành Gemini Web Dual-Quota Bridge v2.0.0', '# Antigravity <-> Gemini Web Dual-Quota Bridge v2.0.0 (Bản Chuẩn Hóa Production-Grade)

## 1. Mục Đích & Vị Trí Lưu Trữ
- **Mục đích:** Tận dụng quota kép giữa Antigravity (Local Agent) và Gemini Chat Web (gemini.google.com) thông qua Chrome Extension chạy ngầm, tốc độ cao, zero-DOM token.
- **Đường dẫn thư mục:** `C:\Users\tvu16\.gemini\antigravity\gemini_web_bridge`
  - `extension/content.js`: Kịch bản tương tác DOM trực tiếp trên tab gemini.google.com (v2.0.0).
  - `extension/manifest.json`: Cấu hình Manifest V3, permissions `storage`, `tabs`, host permissions `gemini.google.com`, `ws://127.0.0.1:8765`.
  - `bridge_daemon.js`: Standalone daemon HTTP + WebSocket (Port 8765), quản lý kết nối và endpoint `/ask`, `/status`, `/inspect`.
  - `ask.js`: CLI bridge script hỗ trợ cờ `--continue`, tự động gọi daemon và chuẩn hóa prompt.
  - `normalizer.js`: Chuẩn hóa prompt với cơ chế Educational Intent Guarantee (v2.0.0).
  - `run_daemon.vbs`: Khởi chạy daemon ngầm hoàn toàn không hiện cửa sổ console hoặc task runner.

## 2. Các Quy Chuẩn Kỹ Thuật Cốt Lõi (v2.0.0)
1. **Cơ chế Gửi Prompt (ProseMirror Native Enter):**
   - Không được dùng `.click()` trần hoặc bắn chuỗi PointerEvent đè lên phím Enter.
   - Sử dụng chuỗi phím Enter native: `keydown` -> `keypress` -> `keyup` (key: ''Enter'', keyCode: 13, bubbles: true, cancelable: true, composed: true) trực tiếp trên `rich-textarea div[contenteditable="true"]`.
   - Chỉ fallback sang click nút Send nếu sau 500ms văn bản trong ô soạn thảo chưa được dọn sạch.
2. **Cơ chế Nhận Diện Nút Dừng (Stop Button Detector):**
   - Tuyệt đối không query thẻ `rect` trong SVG vì toàn bộ Google Material Symbols đều chứa `<rect width="24" height="24" fill="none"/>` gây false-positive liên tục.
   - Nhận diện chính xác theo: nhãn `aria-label` chứa ''dừng phản hồi'', ''dừng tạo'', ''dừng'', ''stop response'', ''stop generating'', hoặc icon text `stop`, `stop_circle`, `pause` tại khu vực thanh nhập liệu đáy.
3. **Cơ chế Giám Sát Dòng Phản Hồi (Anti-Truncation Stream Monitor):**
   - Chỉ kết luận hoàn tất khi:
     - Nút Stop hoàn toàn biến mất khỏi DOM (`!isStillStreaming`).
     - Văn bản đã ngừng biến thiên tối thiểu 2.5 giây (`timeSinceLastChange >= 2500ms`).
     - Nút Sao chép (Copy button) đã thực sự xuất hiện trên DOM (`hasCopyBtn` có bounding rect hợp lệ) HOẶC văn bản đã đứng yên liên tục 4 giây.
     - Failsafe cứng: nếu văn bản không đổi trong 8.0 giây, tự động đóng gói trả về.
4. **Cơ chế Chuyển Phiên Chat (Zero-Reload SPA Navigation):**
   - Tuyệt đối không gán `window.location.href = ''/app''`. Việc này sẽ reload trang, đứt kết nối WebSocket và làm chết script đang chạy.
   - Luôn click vào nút New Chat có sẵn trong DOM (`button[data-test-id="new-chat-button"]`, `a[href="/app"]`, hoặc mở menu sidebar rồi click).
5. **Cơ chế Chuẩn Hóa Prompt (Educational Intent):**
   - Gắn tiền tố `Hãy giải thích chi tiết về: ` cho các câu hỏi thông tin/tri thức để triệt tiêu false-positive từ bộ lọc an toàn 2 tầng (pre/post-response filter) của Google.

## 3. Quy Trình Nạp Khi Sửa Code
- Sau khi chỉnh sửa `extension/content.js` hoặc `manifest.json`:
  1. Mở `brave://extensions` -> Bấm icon 🔄 Tải lại tiện ích.
  2. Mở tab Gemini Web (`gemini.google.com`) -> Nhấn F5.', 'decision', 'gemini-web,bridge,dual-quota,chrome-extension,v2.0.0,architecture', 'agent_mcp', 1.704, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (27, 'Thông tin tải game Diablo II: Resurrected của Ngài', 'Ngài đang tải bộ cài đặt Diablo II: Resurrected (bản LinkNeverDie TCP) bằng phần mềm Free Download Manager (FDM).
- Thư mục lưu trữ: C:\Users\tvu16\Downloads
- Cấu trúc bộ cài: Gồm 3 part dạng file RAR (Part 1: ~13GB, Part 2: ~13GB, Part 3: ~2GB, tổng ~28GB).
- File đang tải sẽ có định dạng *.rar.fdmdownload, khi hoàn tất sẽ tự chuyển thành *.rar.
- Quá trình tải ghi nhận: Part 1 xong trước (22:51 ngày 20/09/2026), Part 2 và Part 3 hoàn tất sau đó.
- Công cụ kiểm tra: Truy vấn SQLite tại %LOCALAPPDATA%\Softdeluxe\Free Download Manager\db.sqlite.', 'fact', 'diablo,d2r,game,fdm,downloads,linkneverdie', 'agent_mcp', 1.164, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (28, 'Diablo II: Resurrected đã giải nén hoàn tất trong Downloads', 'Bộ cài đặt Diablo II: Resurrected (LinkNeverDie TCP) đã được giải nén thành công trọn vẹn vào thư mục Downloads:
- Đường dẫn: C:\Users\tvu16\Downloads\D2R.TCP_LinkNeverDie.Com
- Dung lượng bung nén: ~30.44 GB
- File chạy game: "__Start game TCP + create shortcut.exe" hoặc "__Start game TCP ReMoDDeD + create shortcut.exe"
- Mật khẩu giải nén: linkneverdie.com
- Bộ cài gốc (RAR): C:\Users\tvu16\Downloads\D2R.TCP_LinkNeverDie.Com.part1.rar -> part3.rar (~28 GB)', 'fact', 'diablo,d2r,game,downloads,linkneverdie,extracted', 'agent_mcp', 0.495, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (29, 'Nâng cấp lệnh screenoff thế hệ mới (Eco Agentic Mode) và bổ sung lệnh screenon', 'HỆ THỐNG ECO AGENTIC SCREENOFF THẾ HỆ MỚI (V2.0):
1. Mục tiêu: Khi Ngài tắt màn hình (screenoff), toàn bộ các ứng dụng bên thứ 3 và tác vụ nền ngốn tài nguyên (Brave cá nhân, Zalo, Riot Client, Vanguard, FDM, Spotify, Widgets...) sẽ được đưa vào trạng thái ngủ đông (NtSuspendProcess) và thu hồi RAM (EmptyWorkingSet).
2. Bảo vệ tuyệt đối (Whitelisted 100%):
   - Antigravity (IDE, language_server, node, python, MCP, uv).
   - Gemini Web Bridge (node daemon 127.0.0.1:8765 và Chromium Sidecar với profile chuyên dụng).
   - Windows Core (dwm, explorer, csrss, lsass, services) và Remote Control WebRTC.
   - Phần cứng & Mạng (Lenovo Legion Toolkit, Cloudflare WARP, FastTemp, UniKeyNT, Audio/Display drivers).
3. Phần cứng: Tự động đưa Legion sang Quiet Mode và tắt đèn nền bàn phím để triệt tiêu tiếng ồn quạt và nhiệt lượng.
4. Cơ chế thức tỉnh kép (Dual-Wake):
   - Tự động: Background Watcher phát hiện cử chỉ chuột hoặc gõ phím vật lý tại bàn -> Tự động rã đông (NtResumeProcess) toàn bộ ứng dụng trong < 500ms, phục hồi profile Legion.
   - Chủ động: Gõ ''screenon'' (hoặc ''resume'') trong terminal hoặc bảo Agent ''screenon'' / ''bật màn hình'' để đánh thức màn hình và rã đông tức thì từ xa.', 'SNIPPET', 'screenoff,screenon,display,eco,performance,llt,gemini_web_bridge,hardware', 'agent_mcp', 0.1, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (30, 'Nâng cấp screenoff v2.1: Tự động chuyển đổi Power Saver và Ultimate Performance', 'CẬP NHẬT ECO AGENTIC SCREENOFF (V2.1 - PONYTAIL COMPLIANT):
- Bổ sung chuyển đổi gói nguồn Windows Native qua powercfg:
  1. Khi tắt màn hình (screenoff): Tự động chuyển Windows Power Scheme sang ''Power saver'' (GUID: 538df9f7-dc4f-4a30-844c-a7ce0628d803), giúp chip Ryzen 7 7840H giảm điện áp, giảm công suất tiêu thụ thêm 4-6W và hạ nhiệt độ sâu hơn.
  2. Khi bật máy / mở màn hình (screenon hoặc chạm chuột/bàn phím): Tự động khôi phục ngay lập tức về ''Ultimate Performance'' (GUID: 3a41ddd7-0eea-4292-a049-1ad7a6674099) để Ngài làm việc với toàn bộ sức mạnh phần cứng.
- Triết lý Ponytail: Tận dụng 100% native powercfg của Windows, không thêm thư viện hay tiến trình thừa.
- Trạng thái kiểm thử: Đã test 2 chiều thành công 100%.', 'SNIPPET', 'screenoff,screenon,powersaver,ultimate_performance,powercfg,ponytail,eco', 'agent_mcp', 0.1, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (31, 'Giải mã & Tối ưu hóa sâu gói Power Saver: Hạ công suất APU về 2W và giảm 26 độ C cụm ACPI', 'TỐI ƯU HÓA ĐỈNH CAO POWER SAVER WINDOWS (CHÊ ĐỘ ĐÓNG BĂNG 2W):
1. Vấn đề của Power Saver mặc định:
   - Windows mặc định để PERFBOOSTMODE = Aggressive (2) và PROCTHROTTLEMAX = 100%. CPU AMD Ryzen 7 7840H vẫn bị ép xung gián đoạn lên 4.5-5.1GHz và ăn 18W điện standby, giữ nhiệt độ ở ~53-55°C và cụm ACPI nóng 73°C.
2. Tinh chỉnh sâu qua powercfg native (Ponytail):
   - powercfg /setacvalueindex 538df9f7-dc4f-4a30-844c-a7ce0628d803 SUB_PROCESSOR PERFBOOSTMODE 0 (Tắt Turbo Boost).
   - powercfg /setacvalueindex 538df9f7-dc4f-4a30-844c-a7ce0628d803 SUB_PROCESSOR PROCTHROTTLEMAX 65 (Khóa trần xung ở 2.46 GHz).
3. Kết quả đo đạc thực tế:
   - Công suất APU giảm từ 18.0W xuống 2.0W (giảm 89%).
   - Cảm biến SoC APU giảm từ 55.0°C xuống 46.0°C.
   - Nhiệt độ dGPU RTX 4050 giảm từ 50.0°C xuống 46.0°C.
   - Nhiệt độ cụm tản nhiệt bo mạch ACPI giảm từ 73.0°C xuống 47.0°C (Hạ 26°C kỷ lục).
4. Phối hợp với Ultimate Performance:
   - Screenoff -> Kích hoạt Power Saver tối ưu này (2W, 46°C, quạt tắt hẳn).
   - Screenon / chạm chuột -> Lập tức bật lại Ultimate Performance 100% công suất.', 'SNIPPET', 'powersave,ultimate_performance,powercfg,thermals,ryzen,perfboostmode,optimization', 'agent_mcp', 0.1, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (32, 'Khởi tạo Custom Power Plan chuyên dụng: Antigravity Eco Agent (44 độ C, Never Sleep)', 'KHỞI TẠO CUSTOM POWER PLAN CHUYÊN DỤNG: ANTIGRAVITY ECO AGENT (v2.2):
1. GUID: 14d37a79-56ce-489c-8976-e97796598820 (Tên: ''Antigravity Eco Agent'').
2. Các thông số vàng được đo ni đóng giày:
   - STANDBYIDLE = 0 & HIBERNATEIDLE = 0: Tuyệt đối KHÔNG ngủ (Sleep) hay ngủ đông (Hibernate) hệ thống khi màn hình tắt. Giữ cho Agent Antigravity và Gemini Web Bridge chạy xuyên đêm ổn định 100% không bị ngắt mạng hay ngắt socket.
   - PERFBOOSTMODE = 0: Khóa Turbo Boost giật xung.
   - PROCTHROTTLEMAX = 65%: Khóa trần xung ở 2.46 GHz (điểm ngọt Zen 4).
   - ASPM = 2: Tiết kiệm điện tối đa cho bus PCIe.
3. Hiệu quả thực tế vừa đo đạc:
   - Cả CPU Ryzen 7 và GPU RTX 4050 đều tụt xuống mốc kỷ lục: 44.0 °C!
   - Cụm tản nhiệt bo mạch ACPI giảm xuống: 45.0 °C!
4. Cơ chế tích hợp:
   - ''screenoff'' -> Tự động kích hoạt ''Antigravity Eco Agent''.
   - ''screenon'' (hoặc chạm chuột/phím) -> Tự động trả về ''Ultimate Performance'' 100% công suất.', 'SNIPPET', 'powerplan,custom,antigravity_eco_agent,screenoff,screenon,ryzen,optimization,ponytail', 'agent_mcp', 0.1, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (33, 'Quy chuẩn Tối ưu tự động Screenoff: Loại bỏ screenon, chỉ thức tỉnh khi chạm chuột/phím tại bàn', 'QUY CHUẨN TỐI ƯU TỰ ĐỘNG SCREENOFF HOÀN THIỆN (LOẠI BỎ SCREENON MANUAL):
1. Quyết định loại bỏ hoàn toàn: Đã xóa screenon.cmd và resume.cmd.
2. Lý do: Tránh mọi sự nhầm lẫn giữa trạng thái màn hình tắt phần cứng và lệnh rã đông phần mềm. Khi Ngài ở xa hoặc dùng điện thoại điều khiển Antigravity/Remote Control, máy vẫn giữ 100% chế độ đóng băng siêu tiết kiệm điện Antigravity Eco Agent (43°C, APU 1W).
3. Cơ chế thức tỉnh duy nhất:
   - Khi Ngài ngồi vào bàn làm việc: Chỉ cần chạm nhẹ chuột vật lý hoặc gõ 1 phím bất kỳ trên bàn phím.
   - Watcher ngầm sẽ bắt cử chỉ thực tế tại bàn trong < 500ms, tự động rã đông 65 app và trả về Ultimate Performance.
4. Trạng thái đo đạc thực tế: Cả CPU, GPU và cụm ACPI đều đạt mốc kỷ lục: 43.0 °C!', 'DECISION', 'screenoff,decision,auto_wake,ponytail,second_brain,hardware', 'agent_mcp', 0.1, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (34, 'Kiến trúc Screenoff Tối Giản và Tự Động Rã Đông Tuyệt Đối', 'Quy chuẩn kiến trúc Screenoff & Auto-Wake tối ưu theo triết lý Ponytail:
1. Gộp thống nhất thành 1 tiến trình duy nhất trong screenoff_engine.ps1 (chạy ngầm qua screenoff.cmd), loại bỏ hoàn toàn việc phân mảnh thành 2 script (engine và watcher) gây mất đồng bộ và lỗi race condition.
2. Biên dịch Win32 P/Invoke 1 lần duy nhất ngay từ đầu khi CPU đang ở Ultimate Performance (4.5+ GHz). Tránh lỗi Add-Type biên dịch trong trạng thái Eco 2W (từng gây nghẽn 5-10s và trễ khởi động watcher).
3. Loại bỏ hoàn toàn EmptyWorkingSet: Không ép xả RAM ra pagefile disk để tránh hiện tượng hard page fault bão hòa I/O khi thức giấc.
4. Khi nhận diện chuyển động chuột/phím, lập tức phục hồi Power Plan (Ultimate Performance) và Legion Power Mode (Balance) TRƯỚC TIÊN (<10ms) để CPU vọt lên 4.5+ GHz, sau đó gọi NtResumeProcess x2 lần cho từng tiến trình người dùng để rã đông triệt để 100%.
5. Loại trừ triệt để Riot Vanguard (vgtray) và các host của Windows để không bị xung đột kernel driver anti-cheat.', 'decision', 'screenoff,powermanagement,ponytail,win32', 'agent_mcp', 1.651, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (35, 'Quy tắc Tự động Screenoff và Khôi phục Performance Mode', 'Quy tắc thực thi Screenoff tự động cho Antigravity Agent:
1. Khi Ngài chat ''screenoff'' hoặc yêu cầu tắt màn hình: Trợ lý BẮT BUỘC thực thi ngay lệnh qua terminal (run_command) bằng WMI để tiến trình chạy ngầm hoàn toàn độc lập khỏi Job Object:
   cmd.exe /c "C:\Users\tvu16\AppData\Roaming\Antigravity\bin\screenoff.cmd"
2. Quá trình tắt màn hình:
   - Đình chỉ toàn bộ ứng dụng người dùng nặng (Brave cá nhân, Zalo, Discord, Telegram, Steam...).
   - Giữ nguyên 100% Antigravity, Gemini Sidecar, Riot Vanguard và tiến trình hệ thống.
   - Chuyển Power Scheme sang Antigravity Eco Agent (2W APU) và Legion sang Quiet.
   - Tắt màn hình bằng cả PostMessage Win32 broadcast và LLT.
3. Quá trình thức giấc (khi chạm chuột, nhấn phím hoặc đăng nhập):
   - Phục hồi Power Scheme sang ''Ultimate Performance'' ngay lập tức (<5ms).
   - Chuyển Legion sang chế độ ''performance'' (theo yêu cầu của Ngài).
   - Rã đông toàn bộ ứng dụng với NtResumeProcess gọi 2 lần (xóa triệt để mọi suspend count).
   - Đánh thức màn hình và tự dọn dẹp sạch sẽ.', 'rule', 'screenoff,rule,power_management,automation', 'agent_mcp', 1.9, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (39, 'Cấu hình Whitelist FDM và Gemini Web Bridge trong Screenoff Engine', 'Đã cấu hình ngoại trừ Free Download Manager (FDM), Antigravity và Gemini Web Bridge khỏi cơ chế ngủ đông của screenoff (tại C:\Users\tvu16\AppData\Roaming\Antigravity\bin\screenoff_engine.ps1).
- Nguyên nhân: Trước đó ''fdm'' và ''wenativehost'' nằm trong danh sách $knownTargets cần suspend, khiến NtSuspendProcess đóng băng toàn bộ tiến trình FDM khi tắt màn hình.
- Khắc phục: Đã chuyển ''fdm'', ''wenativehost'', ''fdm5rhwin'', ''helperservice'' sang $protectedList, loại bỏ khỏi $knownTargets, bổ sung cơ chế kiểm tra đường dẫn thư mục FDM và Gemini Web Bridge.
- Đã rã đông toàn bộ tiến trình, đưa máy về trạng thái Normal Performance, và kích hoạt lại các luồng tải đa luồng của Horizon Forbidden West.', 'decision', 'screenoff,fdm,gemini_web_bridge,antigravity,download', 'agent_mcp', 1.4, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (40, 'Quy tắc Kiểm tra Tiến độ Tải file & Game (fdm)', 'Khi Ngài hỏi về tiến độ tải file, game (Horizon Forbidden West, Diablo 2, Blasphemous, Wuchang...), FDM hoặc gõ lệnh ''fdm'' / ''download'': Trợ lý BẮT BUỘC thực thi ngay lập tức lệnh ''fdm'' (hoặc ''fdm <tên_game>'') qua terminal (''run_command''). Lệnh ''fdm'' là công cụ native CLI siêu tốc (< 50ms) đọc trực tiếp từ CSDL Free Download Manager, xuất báo cáo đầy đủ %, dung lượng, các part và trạng thái hoàn tất. Tuyệt đối KHÔNG viết script Python tạm thời, KHÔNG dò tìm file toàn ổ đĩa gây trễ hàng chục bước.', 'rule', 'fdm,download,progress,game,rule,quick-command', 'system_policy', 1, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (41, 'Thông tin tải game Horizon Forbidden West Complete Edition của Ngài', 'Ngài đang tải bộ cài đặt Horizon Forbidden West Complete Edition (LinkNeverDie Google Drive 8 parts, tổng ~74.6 GB + gói Việt Hóa ''Horizon.Forbidden.West.VietHoa.rar'') bằng phần mềm Free Download Manager (FDM).
- Thư mục lưu trữ: C:\Users\tvu16\Downloads
- Cấu trúc: 7 part đầu mỗi part ~14.9 GB, part 8 ~4.39 MB, kèm file Việt hóa 4.91 MB.
- Part 01 và file Việt hóa đã hoàn tất, các part còn lại đang tải đa luồng qua FDM.
- Công cụ kiểm tra nhanh: Lệnh `fdm horizon` (< 50ms).', 'fact', 'horizon,hfw,forbidden_west,game,fdm,downloads,linkneverdie', 'conversation_history', 0.893, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (42, 'Thông số phần cứng chi tiết Laptop Lenovo Legion của Ngài', 'Hạ tầng phần cứng máy tính cá nhân của Ngài:
- Thiết bị: Laptop Lenovo Legion (Hostname: tranvu-galactic-ion, OS: Windows 11, User: tvu16).
- CPU: AMD Ryzen 7 7840H (8 Cores, 16 Threads, Zen 4, 3.8 - 5.1 GHz).
- GPU rời: NVIDIA GeForce RTX 4050 Laptop GPU (6GB GDDR6, TGP ~95-105W).
- iGPU: AMD Radeon 780M (RDNA 3, Hybrid Mode ON).
- Công cụ đo & kiểm soát: Lenovo Legion Toolkit CLI (`llt`), `FastTemp.exe` (đo SoC APU), NVIDIA SMI.
- Lệnh kiểm tra nhiệt độ tức thời: `temp`.', 'fact', 'hardware,legion,ryzen,rtx4050,cpu,gpu,fasttemp,llt', 'system_audit', 0.811, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (43, 'Danh mục game & tiện ích đã tải / cài đặt trên máy Ngài', 'Danh mục các game và phần mềm tiêu biểu Ngài đang sở hữu hoặc tải về trong `C:\Users\tvu16\Downloads`:
1. Diablo II: Resurrected (LinkNeverDie TCP, bung nén tại `C:\Users\tvu16\Downloads\D2R.TCP_LinkNeverDie.Com`, ~30.4 GB).
2. Horizon Forbidden West Complete Edition (~74.6 GB, đang tải qua FDM).
3. Blasphemous 2 (bản v3.0 kèm Việt Hóa và FLiNG Trainer).
4. Wuchang: Fallen Feathers (bản Việt Hóa + Mod Enabler Steam).
5. Tiện ích âm thanh & ngoại vi: Voicemeeter, phần mềm bàn phím WK870, DroidCam Webcam.', 'fact', 'inventory,games,software,diablo,horizon,blasphemous,wuchang,downloads', 'conversation_history', 0.702, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (44, 'Quy chuẩn & Lệnh Kiểm tra Tải Game Riot Games (LMHT, VALORANT, TFT)', 'Khi Ngài hỏi về tiến độ tải, cập nhật hoặc trạng thái các game thuộc Riot Games (LMHT / League of Legends, VALORANT, Teamfight Tactics / ĐTCL):
1. Trợ lý thực thi ngay lập tức lệnh: fdm riot (hoặc fdm lol, fdm valorant) qua terminal (run_command).
2. Tốc độ kiểm tra < 50ms, đọc trực tiếp từ log thời gian thực của Riot Client (%LOCALAPPDATA%\Riot Games\Riot Client\Logs\Riot Client Logs\*_Riot Client.log) và cấu hình metadata.
3. Tuyệt đối KHÔNG chạy lệnh quét đĩa toàn hệ thống, KHÔNG Get-Process đo lường rườm rà gây chậm trễ.', 'rule', 'riot,lol,lmht,valorant,tft,fdm,rule,shortcut', 'auto_extraction', 1.5, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (45, 'Sở thích Game & Hồ sơ Game đã Chinh phục của Ngài', 'Hồ sơ trải nghiệm game của Ngài:
- Phong cách: Tựa lưng ghế sofa thư giãn chơi bằng tay cầm (gamepad/controller), ưu tiên thế giới mở đồ họa đẹp, dung lượng < 100GB.
- Tựa game đã từng chơi / chinh phục: Elden Ring, Marvel''s Spider-Man, The Witcher 3: Wild Hunt.
- Tựa game hiện diện trên máy:
  * Diablo II: Resurrected: Đã giải nén hoàn tất tại C:\Users\tvu16\Downloads\D2R.TCP_LinkNeverDie.Com (~28 GB, 2 bản TCP & TCP ReMoDDeD).
  * Horizon Forbidden West Complete Edition: 11 part RAR (~137 GB) đang tải qua FDM tại C:\Users\tvu16\Downloads\Horizon.Forbidden.West.Complete.Edition-v1.4.59.0_LinkNeverDie.Com\.
  * VALORANT: Đã cài đặt hoàn chỉnh tại C:\Riot Games\VALORANT (~33.5 GB).
  * Wuchang: Fallen Feathers, Blasphemous 2: Các bản cài/mod trong Downloads.', 'fact', 'gaming,profile,preference,elden_ring,witcher3,spiderman,horizon,diablo2,valorant', 'auto_extraction', 1.087, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (46, 'Sửa lỗi tính tiến độ tải FDM theo chunk ratio trong fdm_status.py', 'Đã nâng cấp bộ parser fdm_status.py (C:\Users\tvu16\AppData\Roaming\Antigravity\bin\fdm_status.py) để tính tỷ lệ phần trăm tải qua chunk ratio:
- Cơ chế cũ: Lấy trực tiếp sum(dones) làm số byte, dẫn đến việc các file lớn (14.9 GB) dùng block 256 byte bị hiển thị 0.0% và sai dung lượng thực tế đã tải.
- Cơ chế mới: Tính chunk_ratio = sum(dones) / sizes[0], sau đó nhân với dung lượng file trên đĩa để ra dung lượng thực tế chính xác 100%. Lệnh ''fdm horizon'' giờ đây hiển thị chính xác tiến độ thời gian thực của FDM.', 'decision', 'fdm,fdm_status,fix,download,horizon', 'agent_mcp', 1.326, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (47, 'Trọn bộ cài đặt Horizon Forbidden West Complete Edition đã tải hoàn tất 100%', 'Bộ cài đặt Horizon Forbidden West Complete Edition (LinkNeverDie Google Drive 8 parts, tổng ~105.4 GB + gói Việt Hóa ''Horizon.Forbidden.West.VietHoa.rar'') đã hoàn tất 100% tại C:\Users\tvu16\Downloads vào lúc 03:11 AM ngày 26/09/2026.
- Đầy đủ 8 part RAR (mỗi part 01-07 ~14.9 GB, part 08 ~1.10 GB) và file Việt Hóa (4.91 MB).
- Quy trình tự động giám sát và tắt máy an toàn sau khi hoàn tất đã thực thi trọn vẹn.', 'note', 'horizon,hfw,forbidden_west,game,downloads,completed,shutdown', 'agent_mcp', 0.1, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (48, 'Screenoff Immunity Whitelist: Bảo vệ UXTU không bị đóng băng', 'Đã cập nhật hệ thống Screenoff (C:\Users\tvu16\AppData\Roaming\Antigravity\bin\screenoff_engine.ps1) để bảo vệ vĩnh viễn UXTU (Universal x86 Tuning Utility). 
UXTU được Ngài cấu hình để giới hạn nhiệt độ CPU ở 89 độ C nhằm tối ưu nhiệt.
Quy chuẩn loại trừ (Immunity Whitelist) của Screenoff hiện tại gồm:
1. Antigravity Agent & toàn bộ mcp-* servers
2. Gemini Web Bridge & Dedicated Profile (Chrome sidecar)
3. FDM (Free Download Manager)
4. UXTU (Universal x86 Tuning Utility, process name ''Universal x86 Tuning Utility'', thư mục JamesCJ60)
Tuyệt đối không bị gọi NtSuspendProcess đóng băng khi màn hình tắt. UXTU luôn tiếp tục hoạt động ngầm để duy trì ngưỡng nhiệt 89°C.', 'decision', 'screenoff,uxtu,whitelist,hardware,cpu_temp', 'agent_mcp', 1.363, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (49, 'Thay thế UXTU bằng RyzenAdj Native Hardware Guard 89C', 'Đã gỡ bỏ và vô hiệu hóa hoàn toàn UXTU (Universal x86 Tuning Utility), giải phóng ~372 MB RAM.
Thay thế bằng bộ giải pháp Native Ponytail siêu tối ưu:
1. RyzenAdj v0.19.0 (C native Win32, 140KB): áp trần nhiệt 89°C và Undervolt Curve Optimizer -15 (all core) qua AMD SMU.
2. Watcher phần cứng không tốn CPU (Zero-polling): cpu_limit_watcher.ps1 chạy ngầm qua Scheduled Task ''Antigravity_CPULimit'' (Highest Privileges).
3. Bắt trực tiếp WMI Hardware Indication Events: LENOVO_GAMEZONE_THERMAL_MODE_EVENT (mỗi khi bấm Fn+Q chuyển Quiet/Balance/Performance/Godmode) và LENOVO_AC_PD_EVENT (cắm/rút sạc).
4. Khắc phục triệt để hiện tượng EC firmware reset: Watcher tự động double-tap nạp lại 89°C sau 400ms settle time.
5. Đã kiểm thử thực tế và xác nhận THM LIMIT CORE luôn giữ vững 89.000°C ở cả 4 chế độ: Quiet, Balance, Performance, Godmode.
6. Lệnh tắt nhanh: gõ ''cpu89'' trên bất kỳ terminal nào.', 'decision', 'hardware,ryzenadj,uxtu_replacement,cpu_temp,thermal_limit,89C,ponytail', 'agent_mcp', 1.61, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (50, 'Chiến lược Scalping XAUUSD MT5 (EMA 21/50 + RSI Dynamic + ATR Trailing Stop)', 'Hệ thống chỉ báo & chiến lược scalping vàng XAUUSD trên khung thời gian M5:
1. Tín hiệu vào lệnh (Entry Signal): Giao cắt EMA 21 & EMA 50 xác nhận xu hướng ngắn hạn; RSI 14 (vùng động 35-65) lọc nhiễu sideway; Nến xác nhận (Price Action) vượt đỉnh/đáy gần nhất.
2. Quản lý rủi ro & Chốt lời: Cung cấp điểm vào kèm lý do ngắn, SL tuyệt đối theo ATR(14) x 1.5; TP1 tỷ lệ R:R 1:1 (chốt 50% volume và dời SL về hòa vốn Breakeven); TP2 tỷ lệ R:R 1:2 đến 1:2.5.
3. Chiến lược theo phân khúc vốn:
- Vốn $10: Tài khoản Cent, lot 0.01 micro, max drawdown $2.
- Vốn $100: Tài khoản Standard, lot 0.01 - 0.02, SL $3 - $5, RR 1:1.5.
- Vốn $1,000: Lot 0.05 - 0.10, quản lý lệnh đa tầng với partial profit taking và trailing stop theo cấu trúc thị trường.', 'decision', 'trading,mt5,xauusd,scalping,strategy,money_management', 'agent_mcp', 1.571, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (51, 'Kiến trúc Headless Eco Mode (screenoff) thay thế Windows Sleep khi chạy Agent ngầm', 'Khi chạy tác vụ dài hạn (tải game FDM, Antigravity Agent, Gemini Web Bridge):
1. Tuyệt đối không dùng chế độ Sleep (S3/Modern Standby S0 low-power idle) vì Windows sẽ freeze toàn bộ process mạng, socket và timer của Node.js/Chromium.
2. Giải pháp thay thế hoàn hảo: Chế độ Headless Eco Mode `screenoff` (`cmd.exe /c "C:\Users\tvu16\AppData\Roaming\Antigravity\bin\screenoff.cmd"`). 
Lệnh này tắt màn hình ngay lập tức, hạ xung CPU/điện năng về ngưỡng siêu tiết kiệm (~2W), nhưng vẫn giữ nguyên kết nối mạng và các tiến trình trong Whitelist (Antigravity, Gemini Web Bridge, FDM, UXTU/RyzenAdj) để tiếp tục xử lý công việc ngầm.', 'decision', 'screenoff,sleep,power_management,headless,architecture', 'agent_mcp', 1.389, 'global');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (52, 'Hệ thống Quy tắc và Mẫu Workflow tham khảo từ Everything Claude Code (ECC)', 'Phân tích và bài học tích hợp từ Everything Claude Code (ECC) cho hệ sinh thái Antigravity:
1. Điểm mạnh cốt lõi của ECC là bộ Rule Packs được tinh chỉnh tỉ mỉ cho từng ngôn ngữ lập trình chuyên biệt (TypeScript, Golang, Python, Rust, Java), phân tách rõ ràng giữa Architecture, Testing và Security.
2. Phương án tích hợp tối ưu cho Antigravity: Không cần cài đặt wrapper cồng kềnh, có thể trích xuất trực tiếp các rule pack xuất sắc của ECC để tích hợp thành Custom Skills hoặc Custom Rules trong Antigravity (theo chuẩn Ponytail: nhẹ, không thừa thãi).', 'note', 'claude_code,ecc,rules,best_practices,tooling', 'agent_mcp', 0.1, 'global');
