INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (111, '[hiring] Decision: Fixup+autosquash is the clean way to amend a non-H...', 'Decision: Fixup+autosquash is the clean way to amend a non-HEAD commit without `rebase -i` (disallowed here). `GIT_SEQUENCE_EDITOR=true` auto-applies the fixup editor sequence.', 'decision', 'hiring,decision', 'migration', 1, 'home-tranvu-agent-platform');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (112, '[hiring] Decision: Stateful vs stateless CV route: `/api/hiring/v1/ca...', 'Decision: Stateful vs stateless CV route: `/api/hiring/v1/candidates/:id/cv/upload-url` returns presigned PUT + `s3_key`; UI PUTs file to S3, then `editCandidate({cv_storage_key})` persists the key. Key persisted only after successful PUT — correct pattern.', 'decision', 'hiring,decision', 'migration', 1, 'home-tranvu-agent-platform');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (113, '[hiring] Decision: RBAC on hiring cv route: `hiring.candidate.manage`...', 'Decision: RBAC on hiring cv route: `hiring.candidate.manage` (upload), `.read` (download), `.create` (parse). All check `requirePermission` via HiringError. OK.', 'decision', 'hiring,decision', 'migration', 1, 'home-tranvu-agent-platform');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (114, '[people] Decision: 2 places needed fix: DB schema default AND code in...', 'Decision: 2 places needed fix: DB schema default AND code insert default. Schema default only applies when column omitted from insert; the insert command explicitly sets it, so both must change.', 'decision', 'people,decision', 'migration', 1, 'home-tranvu-agent-platform');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (115, '[people] Decision: `LIFECYCLE_STAGES` enum array order unchanged — on...', 'Decision: `LIFECYCLE_STAGES` enum array order unchanged — only the default changed.', 'decision', 'people,decision', 'migration', 1, 'home-tranvu-agent-platform');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (116, '[hiring] Decision: No changes to mark-filled-dialog.tsx or cancel-req...', 'Decision: No changes to mark-filled-dialog.tsx or cancel-requisition-dialog.tsx — their built-in 250ms `setTimeout(onDone)` after mutation success already handles post-mutation cleanup correctly.', 'decision', 'hiring,decision', 'migration', 1, 'home-tranvu-agent-platform');
