INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (226, '[hiring] Root cause: ToastViewportWrapper was re-promoting popover (c...', 'Root cause: ToastViewportWrapper was re-promoting popover (calling hidePopover() then showPopover()) whenever toast childList mutations occurred. Calling hidePopover() mid-interaction momentarily unmounted the popover from Top Layer, causing click/mouseup events to fall through to underlying <dialog> backdrop handlers (closing detail drawers). Fix: restrict re-promotion strictly to when a modal <dialog open> is opened.', 'fact', 'hiring,bug_fix', 'migration', 1, 'home-tranvu-agent-platform');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (227, '[hiring] Root cause: Toast dismiss button (X) click inside modal dial...', 'Root cause: Toast dismiss button (X) click inside modal dialogs collapsed toast height before click propagation completed, causing the click to fall through to the underlying modal backdrop and close the modal. Fixed by tracking toast interaction timestamps (lastToastInteractionTime) and capturing/cancelling fall-through click events targeting dialog backdrops within 500ms of a toast interaction in ToastViewportWrapper.', 'fact', 'hiring,bug_fix', 'migration', 1, 'home-tranvu-agent-platform');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (228, '[hiring] Root cause for FUT-830 Toast Modal hover/cursor bug: Astryx ...', 'Root cause for FUT-830 Toast Modal hover/cursor bug: Astryx ToastViewport used popover="manual" which placed it in Top Layer #1 on mount. When candidate detail <dialog showModal()> opened, it became Top Layer #2 (above Top Layer #1). Manual showPopover re-promotion didn''t enable native :hover or cursor:pointer across top layers. Solution: React createPortal into the active <dialog> element with isTopLayer={false}. Rendering Toast inside the active dialog top layer context restores 100% native hover, cursor:pointer, and single-click dismissal cleanly without hacky event listeners.', 'fact', 'hiring,bug_fix', 'migration', 1, 'home-tranvu-agent-platform');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (229, '[hiring] FUT-830 Toast Modal Conflict Final Fix: Implemented window c...', 'FUT-830 Toast Modal Conflict Final Fix: Implemented window capture-phase click & pointer handlers combined with MutationObserver popover re-promotion in ToastViewport. This guarantees: 1) Clicking candidate cards enters detail modal cleanly, 2) Clicking Toast X button dismisses toast instantly without modal double-clicks, 3) Cursor pointer & hover state are preserved.', 'fact', 'hiring,bug_fix', 'migration', 1, 'home-tranvu-agent-platform');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (230, '[hiring] FUT-830 PR #586 created for Toast Modal Interaction Fix. Sol...', 'FUT-830 PR #586 created for Toast Modal Interaction Fix. Solved single-click dismissal, hover cursor feedback, and candidate detail drawer compatibility cleanly without DOM portals or hacks.', 'decision', 'hiring,decision', 'migration', 1, 'home-tranvu-agent-platform');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (231, '[hiring] FUT-830 PR #586 squashed into 1 clean commit on top of origi...', 'FUT-830 PR #586 squashed into 1 clean commit on top of origin/main. PR updated with scope fix(hiring), Tier T3, and Hot/Cold review map.', 'decision', 'hiring,decision', 'migration', 1, 'home-tranvu-agent-platform');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (232, '[hiring] FUT-830 PR #586 description fully formatted according to pul...', 'FUT-830 PR #586 description fully formatted according to pull_request_template.md, preserving Risk/What-could-break sections alongside Hot/Cold review map.', 'decision', 'hiring,decision', 'migration', 1, 'home-tranvu-agent-platform');
INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (233, '[hiring] Root cause: 1. `e.preventDefault()` on `onSelect` kept the d...', 'Root cause: 1. `e.preventDefault()` on `onSelect` kept the dropdown open (Radix default behavior is to close on select, prevented to avoid race with Dialog focus-trap opening synchronously)', 'fact', 'hiring,bug_fix', 'migration', 0.518, 'home-tranvu-agent-platform');
