INSERT OR REPLACE INTO knowledge_items (id, title, content, category, tags, source, importance, project_scope) VALUES (235, '[general] Pattern: fail** (`test-antigravity-integration`, `test-memor...', 'Pattern: fail** (`test-antigravity-integration`, `test-memory-mcp-handshake`) — depend on external env. Fix: env-guard → SKIP (exit 0) locally, still run in CI.', 'concept', 'general,pattern', 'migration', 0.6719999999999999, 'home-tranvu-agent-platform');
