INSERT OR REPLACE INTO solutions (id, error_pattern, root_cause, solution_code, command_fix, project_scope, confidence, success_count) VALUES (22, '[QUY TRÌNH] Kiểm tra tiến độ tải game Diablo 2 Resurrected qua Free Download Manager (FDM)', 'FDM pre-allocates file size trên đĩa và lưu trữ bytes đã tải (done/size) dưới dạng QDataStream binary blob trong cột files của SQLite table downloads (%LOCALAPPDATA%\Softdeluxe\Free Download Manager\db.sqlite). Không thể kiểm tra bằng Get-Item FileSize đơn thuần.', 'Quy trình 1 bước kiểm tra live progress FDM: 1. Mở CSDL SQLite FDM ở chế độ read-only mode: `file:C:/Users/tvu16/AppData/Local/Softdeluxe/Free Download Manager/db.sqlite?mode=ro`. 2. Truy vấn bảng `downloads` lọc bản ghi chứa `D2R` (hoặc tên game). 3. Bóc tách nhị phân các block QDataStream: `re.finditer(rb''s\x00i\x00z\x00e\x00\x00\x00\x04(.{8})'')` và `re.finditer(rb''d\x00o\x00n\x00e\x00\x00\x00\x04(.{8})'')` bằng `struct.unpack(''>Q'', ...)`. 4. Tính % tổng và từng part. File hoàn tất sẽ mất đuôi `.fdmdownload` và có `finishedTime > 0`.', 'python -c "import sqlite3, os, re, struct; db = os.path.expandvars(r''%LOCALAPPDATA%\Softdeluxe\Free Download Manager\db.sqlite''); conn = sqlite3.connect(f''file:{db}?mode=ro'', uri=True); c = conn.cursor(); c.execute(''SELECT id, finishedTime, files FROM downloads''); [print(f''ID {fid}: fin={fin}'') for fid, fin, blob in c.fetchall() if b''D\x002\x00R'' in blob]"', 'global', 1, 1);
INSERT OR REPLACE INTO solutions (id, error_pattern, root_cause, solution_code, command_fix, project_scope, confidence, success_count) VALUES (24, 'sqlite3.OperationalError: near "table": syntax error', 'Created At: 2026-09-20T23:09:56+07:00
Completed At: 2026-09-20T23:09:56+07:00

The command exited with code 1.
Output:
Traceback (most recent call last):
  File "<string>", line 1, in <module>
sqlite3.OperationalError: near "table": syntax error

', 'Lệnh khắc phục thành công: python -c \"import sqlite3, os; db = os.path.expanduser(''~\\\\AppData\\\\Local\\\\Softdeluxe\\\\Free Download Manager\\\\db.sqlite''); conn = sqlite3.connect(''file:'' + db + ''?mode=ro'', uri=True); c = conn.cursor(); c.execute(''SELECT name FROM sqlite_master''); print(c.fetchall())\"', 'python -c \"import sqlite3, os; db = os.path.expanduser(''~\\\\AppData\\\\Local\\\\Softdeluxe\\\\Free Download Manager\\\\db.sqlite''); conn = sqlite3.connect(''file:'' + db + ''?mode=ro'', uri=True); c = conn.cursor(); c.execute(''SELECT name FROM sqlite_master''); print(c.fetchall())\"', 'global', 1, 2);
INSERT OR REPLACE INTO solutions (id, error_pattern, root_cause, solution_code, command_fix, project_scope, confidence, success_count) VALUES (25, 'SyntaxError: unterminated string literal (detected at line 31)', 'Created At: 2026-09-20T23:10:25+07:00
Completed At: 2026-09-20T23:10:25+07:00

The command exited with code 1.
Output:
  File "<string>", line 31
    print(f''  Status: {" HO�N TH�NH\
                       ^
SyntaxError: unterminated string literal (detected at line 31)

', 'Lệnh khắc phục thành công: python -c \"\nimport sqlite3, os, re, struct\n\ndb = os.path.expanduser(''~\\\\AppData\\\\Local\\\\Softdeluxe\\\\Free Download Manager\\\\db.sqlite'')\nconn = sqlite3.connect(''file:'' + db + ''?mode=ro'', uri=True)\nc = conn.cursor()\nc.execute(''SELECT id, finishedTime, files FROM downloads WHERE id IN (127, 128, 129)'')\nfor fid, fin, blob in c.fetchall():\n    name_idx = blob.find(b''D\\x002\\x00R'')\n    name = blob[name_idx:name_idx+100].decode(''utf-16le'', errors=''ignore'').split(''\\x00'')[0]\n    \n    sections_pos = blob.find(b''s\\x00e\\x00c\\x00t\\x00i\\x00o\\x00n\\x00s'')\n    total_size = 0\n    total_done = 0\n    if sections_pos != -1:\n        sec_blob = blob[sections_pos:]\n        for m in re.finditer(rb''s\\x00i\\x00z\\x00e\\x00\\x00\\x00\\x04(.{8})'', sec_blob):\n            total_size += struct.unpack(''>Q'', m.group(1))[0]\n        for m in re.finditer(rb''d\\x00o\\x00n\\x00e\\x00\\x00\\x00\\x04(.{8})'', sec_blob):\n            total_done += struct.unpack(''>Q'', m.group(1))[0]\n            \n    # Also get file size on disk if available\n    disk_path = os.path.expanduser(f''~\\\\Downloads\\\\{name}'')\n    fdm_path = disk_path + ''.fdmdownload''\n    exists = os.path.exists(disk_path)\n    fdm_exists = os.path.exists(fdm_path)\n    \n    print(f''File: {name}'')\n    print(f''  FinishedTime: {fin}'')\n    print(f''  Disk status: exists={exists}, fdm_exists={fdm_exists}'')\n    if total_size > 0:\n        pct = (total_done / total_size) * 100\n        print(f''  Progress: {total_done / (1024**3):.2f} GB / {total_size / (1024**3):.2f} GB ({pct:.1f}%)'')\n\"', 'python -c \"\nimport sqlite3, os, re, struct\n\ndb = os.path.expanduser(''~\\\\AppData\\\\Local\\\\Softdeluxe\\\\Free Download Manager\\\\db.sqlite'')\nconn = sqlite3.connect(''file:'' + db + ''?mode=ro'', uri=True)\nc = conn.cursor()\nc.execute(''SELECT id, finishedTime, files FROM downloads WHERE id IN (127, 128, 129)'')\nfor fid, fin, blob in c.fetchall():\n    name_idx = blob.find(b''D\\x002\\x00R'')\n    name = blob[name_idx:name_idx+100].decode(''utf-16le'', errors=''ignore'').split(''\\x00'')[0]\n    \n    sections_pos = blob.find(b''s\\x00e\\x00c\\x00t\\x00i\\x00o\\x00n\\x00s'')\n    total_size = 0\n    total_done = 0\n    if sections_pos != -1:\n        sec_blob = blob[sections_pos:]\n        for m in re.finditer(rb''s\\x00i\\x00z\\x00e\\x00\\x00\\x00\\x04(.{8})'', sec_blob):\n            total_size += struct.unpack(''>Q'', m.group(1))[0]\n        for m in re.finditer(rb''d\\x00o\\x00n\\x00e\\x00\\x00\\x00\\x04(.{8})'', sec_blob):\n            total_done += struct.unpack(''>Q'', m.group(1))[0]\n            \n    # Also get file size on disk if available\n    disk_path = os.path.expanduser(f''~\\\\Downloads\\\\{name}'')\n    fdm_path = disk_path + ''.fdmdownload''\n    exists = os.path.exists(disk_path)\n    fdm_exists = os.path.exists(fdm_path)\n    \n    print(f''File: {name}'')\n    print(f''  FinishedTime: {fin}'')\n    print(f''  Disk status: exists={exists}, fdm_exists={fdm_exists}'')\n    if total_size > 0:\n        pct = (total_done / total_size) * 100\n        print(f''  Progress: {total_done / (1024**3):.2f} GB / {total_size / (1024**3):.2f} GB ({pct:.1f}%)'')\n\"', 'global', 1, 2);
INSERT OR REPLACE INTO solutions (id, error_pattern, root_cause, solution_code, command_fix, project_scope, confidence, success_count) VALUES (26, 'temp thiếu nhiệt độ CPU hoặc hiển thị "Đang ở chế độ tiết kiệm điện" và "Khe tản nhiệt ACPI: N/A"', 'Trong system_temp.py, timeout của FastTemp.exe và PowerShell query_acpi bị đặt là 2 giây. Khi máy ở chế độ Eco Agent (xung CPU bị khóa trần 2.0 GHz), thời gian nạp CLR .NET của FastTemp và PowerShell bị trễ nhẹ (>2.0s), dẫn đến việc cả 2 bị timeout cùng lúc. GPU có fallback qua nvidia-smi nên vẫn hiện nhiệt độ, còn CPU bị rơi vào nhánh N/A.', 'Tăng timeout của query_fast_temp() và query_acpi() trong C:\Users\tvu16\.local\bin\system_temp.py từ 2s lên 4s. Do chạy đa luồng ThreadPoolExecutor, thời gian thực thi bình thường vẫn giữ nguyên (~1.2s), nhưng đảm bảo không bao giờ bị rớt cảm biến CPU khi máy chạy ở mức xung tiết kiệm điện.', '', 'global', 1, 1);
INSERT OR REPLACE INTO solutions (id, error_pattern, root_cause, solution_code, command_fix, project_scope, confidence, success_count) VALUES (29, '[QUY TRÌNH] Kiểm tra tiến độ tải game và tập tin qua Free Download Manager (FDM)', 'FDM pre-allocates file size trên đĩa và lưu trữ bytes đã tải (done/size) dưới dạng QDataStream binary blob trong SQLite table downloads (%LOCALAPPDATA%\Softdeluxe\Free Download Manager\db.sqlite). Không thể kiểm tra bằng Get-Item FileSize đơn thuần.', 'Thực thi ngay lệnh phím tắt `fdm` (hoặc `fdm <tên_game>`) qua terminal (`run_command`) để xuất báo cáo tiến độ thời gian thực đầy đủ %, dung lượng, các part và trạng thái hoàn tất trong < 50ms.', 'fdm', 'global', 1, 50);
INSERT OR REPLACE INTO solutions (id, error_pattern, root_cause, solution_code, command_fix, project_scope, confidence, success_count) VALUES (30, '[QUY TRÌNH] Kiểm tra tiến độ tải game Riot Games (LMHT, VALORANT, TFT) qua Riot Client', 'Cần báo cáo tiến độ tải hoặc cập nhật các game Riot mà không quét đĩa hay chạy script dò tìm log lâu', 'fdm riot', 'fdm riot', 'global', 1, 20);
INSERT OR REPLACE INTO solutions (id, error_pattern, root_cause, solution_code, command_fix, project_scope, confidence, success_count) VALUES (31, 'Gemini Web Bridge báo chưa kết nối hoặc kẹt luồng khi chuyển phiên chat', 'DOM của tab gemini.google.com chưa kịp giải phóng toàn bộ node tin nhắn của cuộc trò chuyện trước khi chuyển URL phiên mới, khiến bridge kiểm tra nhầm trạng thái hoàn tất hoặc kẹt listener.', 'Trong content.js, bắt buộc kiểm tra và xác nhận các node tin nhắn cũ trong DOM đã biến mất hoàn toàn (`document.querySelectorAll(MSG_SELECTOR).length === 0`) và khung chat mới sẵn sàng trước khi cho phép bước tiếp theo thực thi.', '', 'global', 1, 1);
INSERT OR REPLACE INTO solutions (id, error_pattern, root_cause, solution_code, command_fix, project_scope, confidence, success_count) VALUES (35, 'CPU AMD Ryzen 7 nóng quá nhiệt trên laptop Lenovo Legion / EC firmware reset trần nhiệt độ 100°C khi đổi Fn+Q hoặc khởi động lại máy', 'Lenovo EC firmware tự động nạp lại bảng xung nhịp và trần nhiệt mặc định (100°C) mỗi khi đổi chế độ Fn+Q hoặc cắm/rút sạc; các công cụ bên thứ ba như UXTU quá nặng (~372MB RAM) và dễ bị treo khi tắt màn hình.', '1. Dùng RyzenAdj v0.19.0 (140KB C native) áp trần nhiệt 89°C (--tctl-temp=89) và Curve Optimizer -15 (--set-coall=1048561).
2. Tạo Scheduled Task ''Antigravity_CPULimit'' (Highest Privileges) chạy script ''cpu_limit_watcher.ps1''.
3. Sử dụng LogonTrigger và SessionUnlockTrigger để tự động chạy khi khởi động máy hoặc mở khóa.
4. Lắng nghe trực tiếp các sự kiện WMI: LENOVO_GAMEZONE_THERMAL_MODE_EVENT, LENOVO_AC_PD_EVENT và áp dụng kỹ thuật Double-tap (độ trễ 400ms) để ghi đè lại firmware EC.
5. Vòng lặp Win32 Event Loop tĩnh kết hợp nhịp tim 10s để bảo đảm mức tiêu thụ CPU 0% và RAM ~22MB.', 'schtasks /run /tn "Antigravity_CPULimit"', 'global', 1, 1);
INSERT OR REPLACE INTO solutions (id, error_pattern, root_cause, solution_code, command_fix, project_scope, confidence, success_count) VALUES (41, '[QUY TRÌNH] Kiểm tra tiến độ tải game và tập tin qua Free Download Manager (FDM) & Fast-Path SLA', 'Agent trong các phiên trước tự ý sa đà vào điều tra CSDL FDM và refactor mã nguồn trong lúc phục vụ lệnh tải file, gây trễ hơn 2 phút. Đồng thời fdm_status.py thiếu fuzzy matching cho các từ khóa gộp như forza6 hay fh6.', 'Công cụ fdm_status.py đã được nâng cấp toàn diện: 1. Tự động nhận diện token & alias (fh6, forza6, d2r, lol, etc.). 2. Báo cáo tốc độ MB/s thời gian thực và thời gian dự kiến hoàn tất (ETA). 3. Tự động kiểm tra dung lượng trống ổ đĩa đích và đưa ra cảnh báo an toàn. 4. Tự động khử trùng lặp download cũ/mới và chuẩn hóa dung lượng multi-part archive (.part01..12). 5. Áp dụng nghiêm ngặt Fast-Path Non-Blocking SLA: chạy ngay ở Turn 1 (< 3s), tuyệt đối không chặn luồng sửa code ngầm.', 'fdm [tên_game]', 'global', 1, 1);
INSERT OR REPLACE INTO solutions (id, error_pattern, root_cause, solution_code, command_fix, project_scope, confidence, success_count) VALUES (52, '[general] Root cause: `set -euo pipefail` + `grep <pattern> | head -N`...', 'Root cause: `set -euo pipefail` + `grep <pattern> | head -N` (without `|| true`) = script exits 1 when grep finds no match, because `grep` returns 1 on no match and `pipefail` propagates last non-zero exit.', 'Root cause: `set -euo pipefail` + `grep <pattern> | head -N` (without `|| true`) = script exits 1 when grep finds no match, because `grep` returns 1 on no match and `pipefail` propagates last non-zero exit.', '', 'home-tranvu-agent-platform', 1, 1);
INSERT OR REPLACE INTO solutions (id, error_pattern, root_cause, solution_code, command_fix, project_scope, confidence, success_count) VALUES (53, '[general] Root cause: In `.disagree-report.md`, content was `# ⚡ Phản ...', 'Root cause: In `.disagree-report.md`, content was `# ⚡ Phản bác — no issues` — no `|` character → `grep ''|''` exits 1 → pipefail kills resume.sh.', 'Root cause: In `.disagree-report.md`, content was `# ⚡ Phản bác — no issues` — no `|` character → `grep ''|''` exits 1 → pipefail kills resume.sh.', '', 'home-tranvu-agent-platform', 1, 1);
INSERT OR REPLACE INTO solutions (id, error_pattern, root_cause, solution_code, command_fix, project_scope, confidence, success_count) VALUES (54, '[general] Root cause: # Verify the fixed memory-mcp is light + fast to...', 'Root cause: # Verify the fixed memory-mcp is light + fast to cold-start', 'Root cause: # Verify the fixed memory-mcp is light + fast to cold-start', '', 'home-tranvu-agent-platform', 1, 1);
INSERT OR REPLACE INTO solutions (id, error_pattern, root_cause, solution_code, command_fix, project_scope, confidence, success_count) VALUES (55, '[people] Root cause: DB "disk image is malformed" = WAL writer race (...', 'Root cause: DB "disk image is malformed" = WAL writer race (concurrent cron+Stop+daemon)', 'Root cause: DB "disk image is malformed" = WAL writer race (concurrent cron+Stop+daemon)', '', 'home-tranvu-agent-platform', 1, 1);
INSERT OR REPLACE INTO solutions (id, error_pattern, root_cause, solution_code, command_fix, project_scope, confidence, success_count) VALUES (56, '[people] Root cause: semantic MCP 22.9s = per-call subprocess loading...', 'Root cause: semantic MCP 22.9s = per-call subprocess loading model each time', 'Root cause: semantic MCP 22.9s = per-call subprocess loading model each time', '', 'home-tranvu-agent-platform', 1, 1);
INSERT OR REPLACE INTO solutions (id, error_pattern, root_cause, solution_code, command_fix, project_scope, confidence, success_count) VALUES (57, '[hiring] Root cause: ToastViewportWrapper was re-promoting popover (c...', 'Root cause: ToastViewportWrapper was re-promoting popover (calling hidePopover() then showPopover()) whenever toast childList mutations occurred. Calling hidePopover() mid-interaction momentarily unmounted the popover from Top Layer, causing click/mouseup events to fall through to underlying <dialog> backdrop handlers (closing detail drawers). Fix: restrict re-promotion strictly to when a modal <dialog open> is opened.', 'Root cause: ToastViewportWrapper was re-promoting popover (calling hidePopover() then showPopover()) whenever toast childList mutations occurred. Calling hidePopover() mid-interaction momentarily unmounted the popover from Top Layer, causing click/mouseup events to fall through to underlying <dialog> backdrop handlers (closing detail drawers). Fix: restrict re-promotion strictly to when a modal <dialog open> is opened.', '', 'home-tranvu-agent-platform', 1, 1);
INSERT OR REPLACE INTO solutions (id, error_pattern, root_cause, solution_code, command_fix, project_scope, confidence, success_count) VALUES (58, '[hiring] Root cause: Toast dismiss button (X) click inside modal dial...', 'Root cause: Toast dismiss button (X) click inside modal dialogs collapsed toast height before click propagation completed, causing the click to fall through to the underlying modal backdrop and close the modal. Fixed by tracking toast interaction timestamps (lastToastInteractionTime) and capturing/cancelling fall-through click events targeting dialog backdrops within 500ms of a toast interaction in ToastViewportWrapper.', 'Root cause: Toast dismiss button (X) click inside modal dialogs collapsed toast height before click propagation completed, causing the click to fall through to the underlying modal backdrop and close the modal. Fixed by tracking toast interaction timestamps (lastToastInteractionTime) and capturing/cancelling fall-through click events targeting dialog backdrops within 500ms of a toast interaction in ToastViewportWrapper.', '', 'home-tranvu-agent-platform', 1, 1);
INSERT OR REPLACE INTO solutions (id, error_pattern, root_cause, solution_code, command_fix, project_scope, confidence, success_count) VALUES (59, '[hiring] Root cause for FUT-830 Toast Modal hover/cursor bug: Astryx ...', 'Root cause for FUT-830 Toast Modal hover/cursor bug: Astryx ToastViewport used popover="manual" which placed it in Top Layer #1 on mount. When candidate detail <dialog showModal()> opened, it became Top Layer #2 (above Top Layer #1). Manual showPopover re-promotion didn''t enable native :hover or cursor:pointer across top layers. Solution: React createPortal into the active <dialog> element with isTopLayer={false}. Rendering Toast inside the active dialog top layer context restores 100% native hover, cursor:pointer, and single-click dismissal cleanly without hacky event listeners.', 'Root cause for FUT-830 Toast Modal hover/cursor bug: Astryx ToastViewport used popover="manual" which placed it in Top Layer #1 on mount. When candidate detail <dialog showModal()> opened, it became Top Layer #2 (above Top Layer #1). Manual showPopover re-promotion didn''t enable native :hover or cursor:pointer across top layers. Solution: React createPortal into the active <dialog> element with isTopLayer={false}. Rendering Toast inside the active dialog top layer context restores 100% native hover, cursor:pointer, and single-click dismissal cleanly without hacky event listeners.', '', 'home-tranvu-agent-platform', 1, 1);
INSERT OR REPLACE INTO solutions (id, error_pattern, root_cause, solution_code, command_fix, project_scope, confidence, success_count) VALUES (60, '[hiring] FUT-830 Toast Modal Conflict Final Fix: Implemented window c...', 'FUT-830 Toast Modal Conflict Final Fix: Implemented window capture-phase click & pointer handlers combined with MutationObserver popover re-promotion in ToastViewport. This guarantees: 1) Clicking candidate cards enters detail modal cleanly, 2) Clicking Toast X button dismisses toast instantly without modal double-clicks, 3) Cursor pointer & hover state are preserved.', 'FUT-830 Toast Modal Conflict Final Fix: Implemented window capture-phase click & pointer handlers combined with MutationObserver popover re-promotion in ToastViewport. This guarantees: 1) Clicking candidate cards enters detail modal cleanly, 2) Clicking Toast X button dismisses toast instantly without modal double-clicks, 3) Cursor pointer & hover state are preserved.', '', 'home-tranvu-agent-platform', 1, 1);
INSERT OR REPLACE INTO solutions (id, error_pattern, root_cause, solution_code, command_fix, project_scope, confidence, success_count) VALUES (61, '[hiring] Root cause: 1. `e.preventDefault()` on `onSelect` kept the d...', 'Root cause: 1. `e.preventDefault()` on `onSelect` kept the dropdown open (Radix default behavior is to close on select, prevented to avoid race with Dialog focus-trap opening synchronously)', 'Root cause: 1. `e.preventDefault()` on `onSelect` kept the dropdown open (Radix default behavior is to close on select, prevented to avoid race with Dialog focus-trap opening synchronously)', '', 'home-tranvu-agent-platform', 1, 1);
